        /// Рабочий стол есть (QA `-pittOpEcon8g`, FlowV1/V2); в 8д его нет — решение Максима 02.11 (ГС 19:44, п. 1).
        public static bool DeskOn => !OnePitBalance.Econ8dOn;''')
s=s.replace('''            if (ChapterLine.LevelIx >= ix && DeskLevel < ix) return "Рабочий стол\\nСлой " + (ix + 1);
            return ChapterLine.LockText(ix);''','''            return ChapterLine.LockText(ix);''')
