        public const float MotorCycleV3 = 10f, MotorStepV3 = 0.10f;
        static float _qaMotorCycle = -1f, _qaMotorStep = -1f;
        /// Базовый цикл мотора, с: FlowV3 8д — MotorCycleV3, иначе BenchMotorCycle (FlowV1/V2, QA `-pittOpEcon8g`).
