#!/usr/bin/env python3
"""rw-P: темп покупок по логу прогона: <лог>... — строки prod/upg bought/offer, паузы, число одновременных целей."""
import re, sys
def parse(path):
    ev = []
    for ln in open(path, errors='replace'):
        m = re.search(r'\[onepit\] prod (\S+) (bought|offer) t=(\d+):(\d+)', ln)
        if m:
            ev.append((int(m.group(3))*60+int(m.group(4)), 'prod', m.group(1), m.group(2))); continue
        m = re.search(r'\[onepit\] upg buy id=(\S+) lv=(\d+) t=([0-9.]+)', ln)
        if m: ev.append((float(m.group(3)), 'upg', m.group(1)+m.group(2), 'bought'))
    return sorted(ev)
for p in sys.argv[1:]:
    ev = parse(p)
    buys = [e for e in ev if e[3] == 'bought']
    gaps = [(b[0]-a[0], a, b) for a, b in zip(buys, buys[1:])]
    print(p.split('/')[-1], 'покупок', len(buys), 'макс.пауза', max((g[0] for g in gaps), default=0))
    offers = {}
    for t, k, i, w in ev:
        if w == 'offer': offers.setdefault(i, t)
    # открытые цели (circle offers до покупки) по времени
    bought = {i: t for t, k, i, w in ev if k == 'prod' and w == 'bought'}
    pts = []
    for t in range(0, 3000, 60):
        n = sum(1 for i, to in offers.items() if to <= t and (i not in bought or bought[i] > t))
        pts.append(n)
    print('  целей по минутам:', ''.join(str(min(n, 9)) for n in pts[:50]))
EOF
